/**
 * Wire Protocol Types — Pocketmux DataChannel Messages
 *
 * All messages between mobile app and host flow over the WebRTC DataChannel,
 * serialized with MessagePack. These types are the contract between the
 * TypeScript packages (server, mobile) and the Go host agent (which mirrors them).
 */
export interface ListSessionsRequest {
    type: 'list_sessions';
}
export interface AttachRequest {
    type: 'attach';
    paneId: string;
    cols: number;
    rows: number;
    reattach?: boolean;
    compression?: 'deflate';
}
export interface DetachRequest {
    type: 'detach';
}
export interface InputRequest {
    type: 'input';
    data: Uint8Array;
}
export interface ResizeRequest {
    type: 'resize';
    cols: number;
    rows: number;
}
export interface KillSessionRequest {
    type: 'kill_session';
    session: string;
}
export interface CreateSessionRequest {
    type: 'create_session';
}
export interface PingRequest {
    type: 'ping';
}
/**
 * Proof that the connecting peer possesses the X25519 shared secret derived at
 * pairing, bound to this connection's DTLS session. Sent in response to an
 * AuthChallengeEvent as the first DataChannel message.
 *
 * Transcript (byte concatenation, 128 bytes):
 *   T = hostNonce(32) || mobileNonce(32) || hostCertFp(32) || mobileCertFp(32)
 * where hostNonce is the decoded AuthChallengeEvent.nonce, mobileNonce is the
 * decoded `nonce` below, and each certFp is the raw 32-byte SHA-256 of that
 * peer's DER DTLS certificate (the hex-decoded SDP `a=fingerprint:sha-256`).
 * Fingerprints are never sent in messages; each side reads them from the SDP.
 *
 *   mac = base64std(HMAC-SHA256(sharedSecret, ASCII('pocketmux-auth-v2 mobile->host') || T))
 *
 * The host rejects the connection if this is missing, malformed, or fails
 * verification, then proves itself back with an AuthConfirmEvent. This
 * authenticates both peers independently of the (untrusted) signaling server.
 */
export interface AuthResponseRequest {
    type: 'auth_response';
    /** base64std of HMAC-SHA256(sharedSecret, ASCII('pocketmux-auth-v2 mobile->host') || T). */
    mac: string;
    /** base64std of 32 random bytes generated by the mobile for this connection. */
    nonce: string;
}
export type HostRequest = ListSessionsRequest | AttachRequest | DetachRequest | InputRequest | ResizeRequest | KillSessionRequest | CreateSessionRequest | PingRequest | AuthResponseRequest;
export interface SessionsEvent {
    type: 'sessions';
    sessions: TmuxSession[];
    /** Agent version string (e.g., "1.2.3"). Present when agent supports update checking. */
    agentVersion?: string;
    /** Latest available version string if an update is available, undefined otherwise. */
    updateAvailable?: string;
}
export interface OutputEvent {
    type: 'output';
    data: Uint8Array;
}
export interface AttachedEvent {
    type: 'attached';
    paneId: string;
    compression?: 'deflate';
}
export interface DetachedEvent {
    type: 'detached';
}
export interface SessionEndedEvent {
    type: 'session_ended';
    session: string;
}
export interface PaneClosedEvent {
    type: 'pane_closed';
    paneId: string;
}
export interface SessionCreatedEvent {
    type: 'session_created';
    session: TmuxSession;
}
export interface ErrorEvent {
    type: 'error';
    code: string;
    message: string;
}
export interface PongEvent {
    type: 'pong';
    latency: number;
}
/**
 * Per-connection challenge the host sends as the first DataChannel message.
 * The mobile must reply with an AuthResponseRequest whose `mac` covers this
 * nonce, the mobile's own nonce, and both DTLS certificate fingerprints (see
 * AuthResponseRequest for the transcript T). The random nonce binds the proof
 * to this connection, preventing replay of a captured response across sessions.
 */
export interface AuthChallengeEvent {
    type: 'auth_challenge';
    /** base64std of 32 random bytes generated by the host for this connection. */
    nonce: string;
    /**
     * Auth protocol version: 2 for the mutual DTLS-bound handshake. Absent from
     * pmux ≤0.5.5 hosts, which speak v1 (HMAC over the nonce only).
     */
    v?: number;
}
/**
 * Host's proof of the shared secret, sent after it verifies the mobile's
 * AuthResponseRequest. Uses the same transcript T as AuthResponseRequest
 * with a distinct direction label:
 *
 *   mac = base64std(HMAC-SHA256(sharedSecret, ASCII('pocketmux-auth-v2 host->mobile') || T))
 *
 * The mobile must verify this before trusting any further host messages.
 */
export interface AuthConfirmEvent {
    type: 'auth_confirm';
    /** base64std of HMAC-SHA256(sharedSecret, ASCII('pocketmux-auth-v2 host->mobile') || T). */
    mac: string;
}
export type HostEvent = SessionsEvent | OutputEvent | AttachedEvent | DetachedEvent | SessionEndedEvent | PaneClosedEvent | SessionCreatedEvent | ErrorEvent | PongEvent | AuthChallengeEvent | AuthConfirmEvent;
export interface TmuxSession {
    id: string;
    name: string;
    /** Unix timestamp in seconds */
    createdAt: number;
    windows: TmuxWindow[];
    /** Unix timestamp in seconds */
    lastActivityAt: number;
    attached: boolean;
}
export interface TmuxWindow {
    id: string;
    name: string;
    index: number;
    active: boolean;
    panes: TmuxPane[];
}
export interface TmuxPane {
    id: string;
    index: number;
    active: boolean;
    size: {
        cols: number;
        rows: number;
    };
    title: string;
    currentCommand: string;
}
